"""Encode review plates generated by render_backwalk.py."""
import argparse
from pathlib import Path
import subprocess
import imageio_ffmpeg
from PIL import Image, ImageDraw, ImageFont

def main():
    cli=argparse.ArgumentParser()
    cli.add_argument('frames',type=Path)
    cli.add_argument('output',type=Path)
    cli.add_argument('--font',type=Path,default=Path('C:/Windows/Fonts/msyh.ttc'))
    args=cli.parse_args()
    args.output.mkdir(parents=True,exist_ok=True)
    font=ImageFont.truetype(str(args.font),21)
    cmd=[imageio_ffmpeg.get_ffmpeg_exe(),'-v','error','-y','-f','rawvideo',
         '-pixel_format','rgb24','-video_size','1152x664','-framerate','30',
         '-i','pipe:0','-vcodec','libx264','-threads','2','-preset','fast',
         '-crf','18','-pix_fmt','yuv420p','-movflags','+faststart',str(args.output/'CanJiOu_BackCarryWalk.mp4')]
    frames=[]
    for i in range(48):
        canvas=Image.new('RGB',(1152,664),(36,43,44))
        for x,label in [(0,'side'),(576,'rear')]:
            with Image.open(args.frames/f'{label}{i:02d}.png') as tile:
                canvas.paste(tile,(x,54))
        draw=ImageDraw.Draw(canvas)
        draw.text((18,10),'残机偶 · 负重慢走    侧面',(235,222,192),font=font)
        draw.text((594,10),'后侧    0.54 米/秒',(235,222,192),font=font)
        if i==12: canvas.save(args.output/'BackCarryWalk.jpg',quality=91)
        frames.append(canvas.tobytes())
    with subprocess.Popen(cmd,stdin=subprocess.PIPE) as stream:
        for _ in range(4):
            for data in frames:stream.stdin.write(data)
        stream.stdin.close()
        if stream.wait()!=0:raise RuntimeError('FFmpeg encoding failed')
if __name__=='__main__':main()
